"use client";
import { GoogleLogin, type CredentialResponse } from "@react-oauth/google";
import { GoogleOAuthProvider } from "@react-oauth/google";
import { verifyGoogleToken } from "@/lib/google-auth.server";
import { useAuth } from "@/lib/auth";
import { toast } from "sonner";
import { CLIENT_ENV } from "@/lib/env";

export function GoogleSignInButton() {
  const { signInWithGoogle } = useAuth();
  const clientId = CLIENT_ENV.NEXT_PUBLIC_GOOGLE_CLIENT_ID;

  if (!clientId || clientId === "your-client-id.apps.googleusercontent.com") {
    return (
      <button
        type="button"
        disabled
        className="flex w-full items-center justify-center gap-3 border border-border bg-background px-4 py-3 text-[13px] text-muted-foreground opacity-60 cursor-not-allowed"
      >
        <GoogleIcon />
        Google Sign-In (configure client ID)
      </button>
    );
  }

  return (
    <GoogleOAuthProvider clientId={String(clientId)}>
      <div className="flex justify-center">
        <GoogleLogin
          onSuccess={async (res: CredentialResponse) => {
            const token = res.credential;
            if (!token) {
              toast.error("Google Sign-In failed", {
                description: "No credential returned. Try again.",
              });
              return;
            }
            try {
              const profile = await verifyGoogleToken({
                data: { token },
              });
              const profileWithPicture = profile.picture
                ? { name: profile.name, email: profile.email, picture: profile.picture }
                : { name: profile.name, email: profile.email };
              signInWithGoogle(profileWithPicture);
              toast.success(`Signed in as ${profile.name}`);
            } catch (err) {
              toast.error("Sign-In failed", {
                description: err instanceof Error ? err.message : "Token verification failed.",
              });
            }
          }}
          onError={() => {
            toast.error("Google Sign-In cancelled", {
              description: "Try again if this wasn't you.",
            });
          }}
          theme="outline"
          size="large"
          width="320"
          shape="rectangular"
          text="continue_with"
        />
      </div>
    </GoogleOAuthProvider>
  );
}

